//! 📃️ DWG paper layouts retain plot options, named coordinate vectors and references.
use semio_framework_value::{ValueError,ValueRefusalKind};
use crate::standards::v_ac1024::subsets::any::schema::snapshot::*;
use super::number::Projection;
use super::drawing::optional_words;
use super::blocks::{project_handles,reconstruct_handles};
use super::reader::{boolean,full_unsigned,high,low,optional_unsigned,ordinal,word,Reader};
use semio_framework_os_kernel::sqlite_snapshot::artifact::Cell::{Integer as I,Text as T,Real as R};

fn ortho(v:DwgOrthographicView)->&'static str{match v{DwgOrthographicView::None=>"none",DwgOrthographicView::Top=>"top",DwgOrthographicView::Bottom=>"bottom",DwgOrthographicView::Front=>"front",DwgOrthographicView::Back=>"back",DwgOrthographicView::Left=>"left",DwgOrthographicView::Right=>"right"}}
pub(super) fn project(p:&mut Projection<'_,'_>,id:i64,v:&DwgLayout)->Result<(),ValueError>{
 let paper=match v.paper_unit{DwgPlotPaperUnit::Inches=>"inches"};let rotation=match v.rotation{DwgPlotRotation::QuarterTurn=>"quarter_turn"};let area=match v.plot_area{DwgPlotArea::Display=>"display",DwgPlotArea::Layout=>"layout"};let scale=match v.standard_scale{DwgStandardScale::Custom=>"custom",DwgStandardScale::OneToOne=>"one_to_one"};let shade=match v.shade_plot{DwgShadePlot::AsDisplayed=>"as_displayed"};let resolution=match v.shade_plot_resolution{DwgShadePlotResolution::Normal=>"normal"};
 let plot=optional_words(v.plot_view_handle);let visual=optional_words(v.visual_style_handle);let active=optional_words(v.active_viewport_handle);let base=optional_words(v.base_ucs_handle);let named=optional_words(v.named_ucs_handle);
 p.insert_key("dwg_layout",id,&[T(&v.page_setup_name),T(&v.printer_configuration),T(&v.canonical_media_name),T(&v.stylesheet),T(&v.name),T(paper),T(rotation),T(area),R(v.paper_units),R(v.drawing_units),T(scale),R(v.standard_scale_factor),T(shade),T(resolution),I(i64::from(v.shade_plot_dpi)),I(i64::from(v.tab_order)),I(i64::from(v.options.paper_space_linetype_scaling)),R(v.ucs_elevation),T(ortho(v.orthographic_view)),plot[0],plot[1],visual[0],visual[1],I(high(v.block_header_handle)),I(low(v.block_header_handle)),active[0],active[1],base[0],base[1],named[0],named[1]])?;
 let o=&v.plot_options;p.insert_key("dwg_plot_options",id,&[I(i64::from(o.use_standard_scale)),I(i64::from(o.plot_viewport_borders)),I(i64::from(o.plot_with_lineweights)),I(i64::from(o.draw_viewports_first)),I(i64::from(o.model_type)),I(i64::from(o.update_paper)),I(i64::from(o.initializing))])?;
 let mut ordered=0;for(name,values)in [("margins",&v.margins),("paper_size",&v.paper_size),("plot_origin",&v.plot_origin),("plot_window_lower_left",&v.plot_window_lower_left),("plot_window_upper_right",&v.plot_window_upper_right),("paper_image_origin",&v.paper_image_origin),("insertion_base",&v.insertion_base),("limits_minimum",&v.limits_minimum),("limits_maximum",&v.limits_maximum),("ucs_origin",&v.ucs_origin),("ucs_x_axis",&v.ucs_x_axis),("ucs_y_axis",&v.ucs_y_axis),("extents_minimum",&v.extents_minimum),("extents_maximum",&v.extents_maximum)]{
 for(index,value)in values.iter().enumerate(){p.insert("dwg_layout_coordinate",&[I(id),T(name),I(ordered),I(ordinal(index)?),R(*value)])?;ordered+=1;}}
 project_handles(p,"dwg_layout_viewport_handle",id,&v.viewport_handles)
}
pub(super) fn reconstruct(r:&mut Reader<'_,'_,'_>,id:i64)->Result<DwgLayout,ValueError>{
 let row=r.component("dwg_layout",id)?;let o=r.component("dwg_plot_options",id)?;
 let mut vectors:[Vec<f64>;14]=std::array::from_fn(|_|Vec::new());let mut prior=0;
 for row in r.list("dwg_layout_coordinate",1,id,3)?{
 let index=match row.text(2)?{"margins"=>0,"paper_size"=>1,"plot_origin"=>2,"plot_window_lower_left"=>3,"plot_window_upper_right"=>4,"paper_image_origin"=>5,"insertion_base"=>6,"limits_minimum"=>7,"limits_maximum"=>8,"ucs_origin"=>9,"ucs_x_axis"=>10,"ucs_y_axis"=>11,"extents_minimum"=>12,"extents_maximum"=>13,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG layout coordinate vector is unknown"))};
 if index<prior||row.integer(4)?!=ordinal(vectors[index].len())?{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG layout coordinate vectors are out of order"));}prior=index;vectors[index].push(row.real(5)?);
 }
 let [margins,paper_size,plot_origin,plot_window_lower_left,plot_window_upper_right,paper_image_origin,insertion_base,limits_minimum,limits_maximum,ucs_origin,ucs_x_axis,ucs_y_axis,extents_minimum,extents_maximum]=vectors;
 Ok(DwgLayout{page_setup_name:row.text(1)?.into(),printer_configuration:row.text(2)?.into(),canonical_media_name:row.text(3)?.into(),stylesheet:row.text(4)?.into(),name:row.text(5)?.into(),plot_options:DwgPlotOptions{use_standard_scale:boolean(o,1)?,plot_viewport_borders:boolean(o,2)?,plot_with_lineweights:boolean(o,3)?,draw_viewports_first:boolean(o,4)?,model_type:boolean(o,5)?,update_paper:boolean(o,6)?,initializing:boolean(o,7)?},
 margins,paper_size,plot_origin,plot_window_lower_left,plot_window_upper_right,paper_image_origin,insertion_base,limits_minimum,limits_maximum,ucs_origin,ucs_x_axis,ucs_y_axis,extents_minimum,extents_maximum,
 paper_unit:match row.text(6)?{"inches"=>DwgPlotPaperUnit::Inches,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG plot paper unit is unknown"))},rotation:match row.text(7)?{"quarter_turn"=>DwgPlotRotation::QuarterTurn,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG plot rotation is unknown"))},plot_area:match row.text(8)?{"display"=>DwgPlotArea::Display,"layout"=>DwgPlotArea::Layout,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG plot area is unknown"))},
 paper_units:row.real(9)?,drawing_units:row.real(10)?,standard_scale:match row.text(11)?{"custom"=>DwgStandardScale::Custom,"one_to_one"=>DwgStandardScale::OneToOne,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG standard scale is unknown"))},standard_scale_factor:row.real(12)?,shade_plot:match row.text(13)?{"as_displayed"=>DwgShadePlot::AsDisplayed,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG shade plot is unknown"))},shade_plot_resolution:match row.text(14)?{"normal"=>DwgShadePlotResolution::Normal,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG shade plot resolution is unknown"))},shade_plot_dpi:word(row,15)?,tab_order:word(row,16)?,options:DwgLayoutOptions{paper_space_linetype_scaling:boolean(row,17)?},ucs_elevation:row.real(18)?,orthographic_view:match row.text(19)?{"none"=>DwgOrthographicView::None,"top"=>DwgOrthographicView::Top,"bottom"=>DwgOrthographicView::Bottom,"front"=>DwgOrthographicView::Front,"back"=>DwgOrthographicView::Back,"left"=>DwgOrthographicView::Left,"right"=>DwgOrthographicView::Right,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DWG layout orthographic view is unknown"))},
 plot_view_handle:optional_unsigned(row,20,21)?,visual_style_handle:optional_unsigned(row,22,23)?,block_header_handle:full_unsigned(row,24,25)?,active_viewport_handle:optional_unsigned(row,26,27)?,base_ucs_handle:optional_unsigned(row,28,29)?,named_ucs_handle:optional_unsigned(row,30,31)?,viewport_handles:reconstruct_handles(r,"dwg_layout_viewport_handle",id)?})
}
